#include "preferences_ui.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static void seed(rtp_preferences *p){rtp_preferences_init(p);assert(rtp_preferences_register(p,"rt-root","",RTP_ENTRY_CATEGORY,1,1)==0);assert(rtp_preferences_register(p,"connectivity","rt-root",RTP_ENTRY_CATEGORY,1,20)==0);assert(rtp_preferences_register(p,"system-tools","rt-root",RTP_ENTRY_CATEGORY,1,10)==0);assert(rtp_preferences_register(p,"ftp-auto","connectivity",RTP_ENTRY_SETTING,1,10)==0);assert(rtp_preferences_register(p,"vita-shell","system-tools",RTP_ENTRY_TOOL,1,10)==0);assert(rtp_preferences_register(p,"hidden-tool","system-tools",RTP_ENTRY_TOOL,0,20)==0);}
int main(void){rtp_preferences p;rtp_preferences_ui ui;rtp_ui_row rows[RTP_UI_MAX_ROWS];size_t n;rtp_profile_store profiles;seed(&p);rtp_preferences_ui_init(&ui);assert(rtp_preferences_ui_rows(&ui,&p,rows,RTP_UI_MAX_ROWS,&n)==0&&n==1&&!strcmp(rows[0].id,"rt-root"));assert(rtp_preferences_ui_enter(&ui,&p,"rt-root")==0);assert(rtp_preferences_ui_rows(&ui,&p,rows,RTP_UI_MAX_ROWS,&n)==0&&n==2);assert(!strcmp(rows[0].id,"system-tools"));assert(rtp_preferences_ui_move(&ui,&p,"system-tools",1)==0);assert(rtp_preferences_ui_rows(&ui,&p,rows,RTP_UI_MAX_ROWS,&n)==0&&!strcmp(rows[1].id,"system-tools"));assert(rtp_preferences_ui_enter(&ui,&p,"system-tools")==0);assert(rtp_preferences_ui_rows(&ui,&p,rows,RTP_UI_MAX_ROWS,&n)==0&&n==1&&!strcmp(rows[0].id,"vita-shell"));assert(rtp_preferences_ui_set_visible(&ui,&p,"vita-shell",0)==0);assert(rtp_preferences_ui_rows(&ui,&p,rows,RTP_UI_MAX_ROWS,&n)==RTP_UI_EMPTY);assert(rtp_preferences_ui_set_visible(&ui,&p,"vita-shell",1)==0);assert(rtp_preferences_ui_back(&ui)==0);assert(rtp_preferences_ui_reset(&ui,&p,"system-tools")==0);rtp_profiles_init(&profiles);assert(rtp_profiles_create(&profiles,"default","Default",&p)==0);assert(rtp_preferences_ui_enter(&ui,&p,"rt-root")==0);assert(rtp_preferences_ui_apply_profile(&ui,&p,&profiles,"default")==0);assert(!strcmp(rtp_preferences_ui_current_category(&ui),""));assert(rtp_preferences_ui_back(&ui)==RTP_UI_ROOT);puts("Preferences UI model tests passed.");return 0;}
